from ortools.linear_solver import pywraplp
import json

def main():
    num_employees = 40
    num_teams = 8
    num_dimensions = 4

    competency_score = [[0]*num_dimensions for _ in range(num_employees)]

    for emp in [3,6,7,12,18,19,20,21,23,25,29,31,33,35,36,38]:
        competency_score[emp-1][0] = 1

    for emp in [1,2,3,5,6,9,11,12,14,16,17,18,19,20,23,24,26,29,30,31,32,33,35,36,37,39]:
        competency_score[emp-1][1] = 1

    for emp in [2,3,5,8,10,11,12,16,21,23,27,28,30,32,37,39]:
        competency_score[emp-1][2] = 1

    for emp in [2,6,9,10,11,12,14,15,18,20,21,23,25,27,28,29,31,33,35,36,37]:
        competency_score[emp-1][3] = 1

    mean_comp = [
        sum(competency_score[i][d] for i in range(num_employees)) / num_teams
        for d in range(num_dimensions)
    ]

    solver = pywraplp.Solver.CreateSolver("SCIP")
    if not solver:
        return

    INF = solver.infinity()

    assign = {}
    for i in range(num_employees):
        for t in range(num_teams):
            assign[(i,t)] = solver.BoolVar(f"a[{i},{t}]")

    team_comp = {}
    for t in range(num_teams):
        for d in range(num_dimensions):
            team_comp[(t,d)] = solver.NumVar(0, INF, f"tc[{t},{d}]")

    abs_dev = {}
    for t in range(num_teams):
        for d in range(num_dimensions):
            abs_dev[(t,d)] = solver.NumVar(0, INF, f"ad[{t},{d}]")

    for i in range(num_employees):
        solver.Add(sum(assign[(i,t)] for t in range(num_teams)) == 1)

    for t in range(num_teams):
        solver.Add(sum(assign[(i,t)] for i in range(num_employees)) >= 1)

    for t in range(num_teams):
        for d in range(num_dimensions):
            solver.Add(
                team_comp[(t,d)] ==
                sum(competency_score[i][d] * assign[(i,t)] for i in range(num_employees))
            )

    for t in range(num_teams):
        for d in range(num_dimensions):
            solver.Add(abs_dev[(t,d)] >= team_comp[(t,d)] - mean_comp[d])
            solver.Add(abs_dev[(t,d)] >= mean_comp[d] - team_comp[(t,d)])

    solver.Minimize(solver.Sum(abs_dev[(t,d)] for t in range(num_teams) for d in range(num_dimensions)))

    status = solver.Solve()

    if status in (pywraplp.Solver.OPTIMAL, pywraplp.Solver.FEASIBLE):
        total_imbalance = solver.Objective().Value()
        assignment_list = []
        for i in range(num_employees):
            for t in range(num_teams):
                if assign[(i,t)].solution_value() > 0.5:
                    assignment_list.append(t + 1)
                    break
        print(json.dumps({
            "employee_team_assignment": assignment_list,
            "total_competency_imbalance": total_imbalance
        }))
    else:
        print(json.dumps({"employee_team_assignment": [], "total_competency_imbalance": -1}))

if __name__ == "__main__":
    main()
